examples.template:
MonarchThemeToggle(
    scheme = scheme,
    onSchemeChange = { scheme = it },
    icon = { choice ->
        MonarchIcon(
            when (choice) {
                MonarchScheme.Light -> SampleIcons.LightMode
                MonarchScheme.Dark -> SampleIcons.DarkMode
                MonarchScheme.System -> SampleIcons.Devices
            },
            contentDescription = null,
            size = MonarchIconSize.Sm,
        )
    },
)

